export function RecordDialog({ open, title, rows, form, fields, tabs, lookups, saving, onOpenChange, onChange, onNavigate, onCodeBlur, onSalaryItemCreated, onTaxExemptionCreated, messagesRef, onNew, onSave, onDelete }: { open: boolean; title: string; rows: any[]; form: any; fields: Field[]; tabs?: { value: string; label: string; fields: Field[] }[]; lookups?: any; saving: boolean; onOpenChange: (v: boolean) => void; onChange: (v: any) => void; onNavigate?: (v: any) => void; onCodeBlur?: () => void; onSalaryItemCreated?: (item: any) => void; onTaxExemptionCreated?: (item: any) => void; messagesRef?: any; onNew: () => void; onSave: () => void; onDelete?: () => void }) {
  const { fullscreenEnabled } = useWorkspace()
  const index = rows.findIndex(r => r.id === form.id), nav = (i: number) => rows[i] && (onNavigate || onChange)({ ...rows[i] })
  const nameRef = useRef<HTMLInputElement>(null)
  const [deleteConfirm, setDeleteConfirm] = useState(false)
  const renderFields = (items: Field[], compact = false) => <div className={`grid gap-4 sm:grid-cols-2 ${compact ? "" : "lg:grid-cols-4"}`}>{items.map(f => <FormField key={f.key} field={f} value={form[f.key]} onChange={v => onChange({ ...form, [f.key]: v, ...(f.key === "father_account" ? { father_account_code: v } : {}) })} />)}</div>
  useEffect(() => {
    if (open && tabs) window.requestAnimationFrame(() => nameRef.current?.focus())
  }, [open, form.id, Boolean(tabs)])
  useEffect(() => {
    if (!open || !tabs) return
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "F3") { event.preventDefault(); onSave() }
      else if (event.key === "F9" && Number(form.id) > 0 && onDelete) { event.preventDefault(); setDeleteConfirm(true) }
      else if (event.key === "Enter" && !event.shiftKey && !event.ctrlKey && !event.altKey && (event.target as HTMLElement)?.tagName !== "TEXTAREA") {
        const target = event.target as HTMLElement
        const dialog = target.closest('[role="dialog"]')
        if (!dialog) return
        event.preventDefault()
        const controls = Array.from(dialog.querySelectorAll<HTMLElement>('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled])')).filter(control => control.tabIndex !== -1)
        controls[controls.indexOf(target) + 1]?.focus()
      }
    }
    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [open, tabs, form.id, onSave, onDelete])
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent inline={fullscreenEnabled && open} className={`flex max-h-[96vh] w-[98vw] flex-col overflow-hidden p-0 ${tabs ? "max-w-[1500px]" : "max-w-6xl rounded-2xl"}`} dir="rtl"><UniversalToolbar currentRecord={index >= 0 ? index + 1 : 0} totalRecords={rows.length} onNew={onNew} onSave={onSave} onDelete={onDelete ? () => setDeleteConfirm(true) : undefined} canDelete={Number(form.id) > 0} onFirst={() => nav(0)} onPrevious={() => nav(Math.max(0, index - 1))} onNext={() => nav(Math.min(rows.length - 1, index + 1))} onLast={() => nav(rows.length - 1)} isSaving={saving} isNewRecord={!form.id} isFirstRecord={rows.length === 0 || index === 0} isLastRecord={rows.length === 0 || index === rows.length - 1} /><div className="min-h-0 flex-1 overflow-y-auto bg-slate-50/60 p-3 text-right"><DialogHeader className="mb-3 rounded-xl bg-gradient-to-l from-emerald-600 to-teal-600 px-4 py-3 text-white shadow"><DialogTitle className="text-right text-white">{title}{!form.id && <span className="mr-2 text-sm font-normal text-emerald-50">(إضافة)</span>}</DialogTitle></DialogHeader>{messagesRef && <Messages innerRef={messagesRef} />}{tabs && <EmployeeIdentity form={form} onChange={onChange} onCodeBlur={onCodeBlur} nameRef={nameRef} />}<Card><CardContent className="p-3 sm:p-4">{tabs ? <Tabs defaultValue={tabs[0]?.value} dir="rtl" className="text-right"><TabsList className="mb-3 flex h-auto w-full flex-wrap justify-start gap-1 rounded-none border-b bg-transparent p-0">{tabs.map(tab => <TabsTrigger key={tab.value} value={tab.value} className="rounded-t-lg border border-b-0 px-4 py-2 data-[state=active]:bg-white data-[state=active]:text-sky-600">{tab.label}</TabsTrigger>)}</TabsList>{tabs.map(tab => <TabsContent key={tab.value} value={tab.value} className="mt-0 min-h-56 rounded-lg border border-slate-200 bg-white p-4" dir="rtl"><div className={tab.value === "salary" || tab.value === "tax" || tab.value === "account" ? "grid gap-4 lg:grid-cols-2" : ""}><div>{renderFields(tab.fields, tab.value === "salary" || tab.value === "tax" || tab.value === "account")}</div><EmployeeTabExtra tab={tab.value} form={form} lookups={lookups || {}} onChange={onChange} onSalaryItemCreated={onSalaryItemCreated} onTaxExemptionCreated={onTaxExemptionCreated} /></div></TabsContent>)}</Tabs> : renderFields(fields)}</CardContent></Card></div><ConfirmDialogYesNo visible={deleteConfirm} message="هل أنت متأكد من حذف الموظف؟" onConfirm={() => { setDeleteConfirm(false); onDelete?.() }} onCancel={() => setDeleteConfirm(false)} /></DialogContent></Dialog>
}
export function DefinitionsPage({ resource, title, fields }: { resource: string; title: string; fields: Field[] }) {
  const blank = useCallback(() => Object.fromEntries(fields.map(f => [f.key, f.type === "checkbox" ? true : ""])), [fields])
  const [rows, setRows] = useState<any[]>([]), [form, setForm] = useState<any>(blank()), [selected, setSelected] = useState<any>(null), [open, setOpen] = useState(false), [saving, setSaving] = useState(false), [search, setSearch] = useState(""), [status, setStatus] = useState("active")
  const load = useCallback(async () => { const r = await fetch(`/api/hr/${resource}`); setRows(r.ok ? await r.json() : []) }, [resource]); useEffect(() => { void load() }, [load])
  const show = (r?: any) => { setForm(r ? { ...r } : blank()); setOpen(true) }
  const save = async () => { if (fields.some(f => f.required && !String(form[f.key] ?? "").trim())) return alert("أكمل الحقول المطلوبة"); setSaving(true); const r = await fetch(`/api/hr/${resource}`, { method: form.id ? "PUT" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); if (r.ok) { await load(); setOpen(false) } else alert((await r.json()).error || "تعذر الحفظ"); setSaving(false) }
  const remove = async () => { if (!form.id || !confirm("هل تريد حذف السجل؟")) return; if ((await fetch(`/api/hr/${resource}?id=${form.id}`, { method: "DELETE" })).ok) { await load(); setOpen(false) } }
  const filtered = rows.filter(r => (status === "all" || !!r.is_active === (status === "active")) && Object.values(r).join(" ").toLowerCase().includes(search.toLowerCase()))
  const cols: Column[] = fields.filter(f => f.type !== "textarea").map(f => ({ key: f.key, label: f.label, type: f.type === "number" ? "number" : f.type === "checkbox" ? "boolean" : undefined, format: f.type === "select" ? v => f.options?.find(o => String(o.value) === String(v))?.label || v : undefined }))
  return <HrPage title={title}><ListActions onNew={() => show()} onEdit={() => selected && show(selected)} onRefresh={load} onPrint={() => window.print()} /><FilterBar search={search} onSearch={setSearch} status={status} onStatus={setStatus} count={filtered.length} /><Grid rows={filtered} columns={cols} onSelect={setSelected} onDoubleClick={show} /><RecordDialog open={open} title={title} rows={rows} form={form} fields={fields} saving={saving} onOpenChange={setOpen} onChange={setForm} onNew={() => setForm(blank())} onSave={save} onDelete={remove} /></HrPage>
}
